    inline const std::unordered_map<std::int32_t, std::string_view>
        ITEM_ID_TO_SHORTNAME = []
        {
            std::unordered_map<std::int32_t, std::string_view> result;
            result.reserve(ITEMS.size());

            for (const ItemEntry& item : ITEMS)
                result.emplace(item.item_id, item.shortname);

            return result;
        }();

    inline const std::unordered_map<std::string_view, std::int32_t>
        SHORTNAME_TO_ITEM_ID = []
        {
            std::unordered_map<std::string_view, std::int32_t> result;
            result.reserve(ITEMS.size());

            for (const ItemEntry& item : ITEMS)
                result.emplace(item.shortname, item.item_id);

            return result;
        }();

    inline bool try_get_shortname(
        std::int32_t item_id,
        std::string_view& shortname) noexcept
    {
        const auto it = ITEM_ID_TO_SHORTNAME.find(item_id);
        if (it == ITEM_ID_TO_SHORTNAME.end())
            return false;

        shortname = it->second;
        return true;
    }

    inline bool try_get_item_id(
        std::string_view shortname,
        std::int32_t& item_id) noexcept
    {
        const auto it = SHORTNAME_TO_ITEM_ID.find(shortname);
        if (it == SHORTNAME_TO_ITEM_ID.end())
            return false;

        item_id = it->second;
        return true;
    }

    inline std::string_view get_shortname(std::int32_t item_id) noexcept
    {
        const auto it = ITEM_ID_TO_SHORTNAME.find(item_id);
        return it != ITEM_ID_TO_SHORTNAME.end()
            ? it->second
            : std::string_view{};
    }

    inline std::int32_t get_item_id(std::string_view shortname) noexcept
    {
        const auto it = SHORTNAME_TO_ITEM_ID.find(shortname);
        return it != SHORTNAME_TO_ITEM_ID.end() ? it->second : 0;
    }
